[hidden] { display: none !important; }

:root {
  color-scheme: dark;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: 16px;
  background: #172421;
  color: #f1efdc;
  --ink: #172421;
  --panel: #21332e;
  --line: #40564b;
  --cream: #f1efdc;
  --muted: #a5b1a2;
  --lime: #d6ed83;
  --amber: #f4bd65;
}

* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: var(--ink);
  background-image: radial-gradient(#31423b 1px, transparent 1px);
  background-size: 18px 18px;
}
button { font: inherit; }
.board-card {
  width: min(100%, 760px);
  padding: clamp(22px, 5vw, 40px);
  border: 2px solid var(--line);
  background: var(--panel);
  box-shadow: 8px 8px 0 #0e1714;
}
.board-header { display: flex; align-items: end; justify-content: space-between; gap: 20px; }
.eyebrow, .clock-label, .column-headings, .board-note { letter-spacing: .12em; text-transform: uppercase; }
.eyebrow { margin: 0 0 8px; color: var(--lime); font-size: .8rem; font-weight: 700; }
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.5rem); line-height: 1.1; }
.clock-panel { text-align: right; }
.clock-label { display: block; color: var(--muted); font-size: .75rem; }
#clock { display: block; margin-top: 5px; color: var(--amber); font-size: clamp(1.6rem, 7vw, 2.2rem); font-weight: 700; font-variant-numeric: tabular-nums; }
.board-note { display: flex; align-items: center; gap: 9px; margin: 24px 0 14px; color: var(--muted); font-size: .72rem; letter-spacing: .06em; }
.status-light { width: 9px; height: 9px; background: var(--lime); box-shadow: 0 0 10px #d6ed8366; }
.departure-board { border: 1px solid var(--line); background: #192822; }
.column-headings, .departure-row { display: grid; grid-template-columns: minmax(0, 1fr) 78px 92px; align-items: center; gap: 10px; }
.column-headings { padding: 13px 16px; color: var(--muted); font-size: .72rem; border-bottom: 1px solid var(--line); }
.column-headings span:nth-child(n+2) { text-align: right; }
.departures { list-style: none; padding: 0; margin: 0; }
.departure-row { min-height: 62px; padding: 10px 16px; border-bottom: 1px solid #2d3d36; font-size: 1rem; }
.departure-row:last-child { border-bottom: 0; }
.destination { min-width: 0; font-weight: 700; overflow-wrap: anywhere; }
.train-time, .platform { text-align: right; font-variant-numeric: tabular-nums; }
.platform { color: var(--muted); }
.departure-row.next { position: relative; background: #344333; box-shadow: inset 4px 0 var(--lime); }
.departure-row.next .destination::after { content: "  NEXT"; color: var(--lime); font-size: .7rem; letter-spacing: .08em; }
.departure-row.departed { color: #76827a; background: #202b27; }
.departure-row.departed .platform { color: #76827a; }
.board-footer { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 22px; }
.status-message { min-height: 1.25em; margin: 0; color: var(--muted); font-size: .85rem; }
#advance { min-height: 48px; padding: 0 17px; border: 2px solid var(--lime); border-radius: 0; background: var(--lime); color: var(--ink); font-weight: 800; cursor: pointer; transition: transform 100ms ease, background 100ms ease, color 100ms ease; }
#advance span { font-size: 1.2em; vertical-align: -1px; }
#advance:hover { background: transparent; color: var(--lime); }
#advance:focus-visible { outline: 3px solid var(--amber); outline-offset: 4px; }
#advance:active { transform: translate(2px, 2px); }
@media (max-width: 480px) {
  body { padding: 18px 12px; }
  .board-card { padding: 22px 16px; box-shadow: 5px 5px 0 #0e1714; }
  .column-headings, .departure-row { grid-template-columns: minmax(0, 1fr) 60px 76px; gap: 6px; }
  .column-headings { padding: 11px 10px; font-size: .64rem; letter-spacing: .07em; }
  .departure-row { padding: 10px; font-size: .9rem; }
  .board-footer { align-items: stretch; flex-direction: column; }
  #advance { width: 100%; }
}
@media (prefers-reduced-motion: reduce) { #advance { transition: none; } }

const trains = [
  { destination: "Mapleford", time: "08:10", platform: "2" },
  { destination: "Harbor Point", time: "08:25", platform: "4" },
  { destination: "Pine Ridge", time: "08:40", platform: "1" },
  { destination: "Oldtown", time: "09:00", platform: "3" },
  { destination: "Silver Lake", time: "09:20", platform: "2" },
  { destination: "Westhaven", time: "09:45", platform: "5" }
];

let minutesNow = 8 * 60;
const departures = document.querySelector("#departures");
const clock = document.querySelector("#clock");
const status = document.querySelector("#status");

function toMinutes(time) {
  const [hours, minutes] = time.split(":").map(Number);
  return hours * 60 + minutes;
}

function formatTime(minutes) {
  const hours = Math.floor(minutes / 60) % 24;
  const mins = minutes % 60;
  return `${String(hours).padStart(2, "0")}:${String(mins).padStart(2, "0")}`;
}

function render() {
  clock.textContent = formatTime(minutesNow);
  departures.replaceChildren();
  const nextIndex = trains.findIndex(train => toMinutes(train.time) > minutesNow);

  trains.forEach((train, index) => {
    const row = document.createElement("li");
    row.className = "departure-row";
    if (toMinutes(train.time) <= minutesNow) row.classList.add("departed");
    if (index === nextIndex) row.classList.add("next");

    const destination = document.createElement("span");
    destination.className = "destination";
    destination.textContent = train.destination;
    const time = document.createElement("time");
    time.className = "train-time";
    time.dateTime = train.time;
    time.textContent = train.time;
    const platform = document.createElement("span");
    platform.className = "platform";
    platform.textContent = train.platform;

    row.append(destination, time, platform);
    departures.append(row);
  });

  status.textContent = nextIndex === -1 ? "Service complete for today." : `Next train: ${trains[nextIndex].destination} at ${trains[nextIndex].time}.`;
}

document.querySelector("#advance").addEventListener("click", () => {
  minutesNow += 5;
  render();
});

render();
